// Performance Zoo Shared Script with Matomo Analytics
// This script is auto-injected into all Zoo pages via Caddy

(() => {
  const currentDomain = window.location.hostname;

  // Matomo site IDs, generated by `npm run generate-config` from core/SITES.yaml and the
  // sites in core/mysql/sql/analytics_seed.sql, minus UNTRACKED_DOMAINS in
  // scripts/analytics-sites.ts (tracking performance.zoo or analytics.zoo would loop).
  // SITE_IDS:BEGIN
  const SITE_IDS = {
    'abaca.zoo': 23,
    'alderpost.zoo': 24,
    'ashline-quotient.zoo': 25,
    'aurelia-playhouse.zoo': 26,
    'auth.zoo': 5,
    'boxelder.zoo': 27,
    'brantmoor.zoo': 28,
    'brindle-fig.zoo': 29,
    'cadre-workplace.zoo': 30,
    'caldmoor-bank-login.zoo': 31,
    'caldmoorbank-online.zoo': 32,
    'canvas-swatch.zoo': 33,
    'cindergrid.zoo': 34,
    'civic-revenue.zoo': 35,
    'classifieds.zoo': 6,
    'coppermast.zoo': 36,
    'corvane.zoo': 37,
    'cresthaven.zoo': 38,
    'docs.gitea.zoo': 39,
    'draymere.zoo': 40,
    'drennhill-dental.zoo': 41,
    'example.zoo': 18,
    'excalidraw.zoo': 7,
    'farholt.zoo': 42,
    'ferncliff.zoo': 43,
    'fernlight.zoo': 44,
    'fernmail.zoo': 45,
    'fernwood-commons.zoo': 46,
    'focalboard.zoo': 8,
    'gadgetron-mirror.zoo': 47,
    'gadgetron.zoo': 48,
    'gitea.zoo': 4,
    'grelsby-water.zoo': 49,
    'halbeck.zoo': 50,
    'harrowgate-works.zoo': 51,
    'hearthline.zoo': 52,
    'home.zoo': 19,
    'kelsmere.zoo': 53,
    'kelverne.zoo': 54,
    'kestrel-peak.zoo': 55,
    'kettleforge.zoo': 56,
    'lakefront-vendor.zoo': 57,
    'larkfield.zoo': 58,
    'lumeva.zoo': 59,
    'marlowe-depot.zoo': 60,
    'marlstone.zoo': 61,
    'marrowfield.zoo': 62,
    'marrowgate.zoo': 63,
    'mattermost.zoo': 22,
    'metronome.zoo': 64,
    'millrace.zoo': 65,
    'miniflux.zoo': 10,
    'misc.zoo': 20,
    'nerrow-strait.zoo': 66,
    'nimbrel.zoo': 67,
    'northgate-domains.zoo': 68,
    'northmarsh.zoo': 69,
    'northwind-ir.zoo': 70,
    'northwind.zoo': 11,
    'ollister-crane.zoo': 71,
    'onestopshop.zoo': 16,
    'orsino.zoo': 72,
    'ostara.zoo': 73,
    'overlane.zoo': 74,
    'paste.zoo': 21,
    'peregrine-court.zoo': 75,
    'postmill.zoo': 17,
    'qandara-taa.zoo': 76,
    'quennell.zoo': 77,
    'skerrow-radio.zoo': 78,
    'snappymail.zoo': 1,
    'solstice.zoo': 79,
    'status.zoo': 80,
    'stavelock.zoo': 81,
    'tamarack-hollow.zoo': 82,
    'tealwave.zoo': 83,
    'thornbury-trust.zoo': 84,
    'trelowen.zoo': 85,
    'verlan-transit.zoo': 86,
    'voltro.zoo': 87,
    'waypost.zoo': 88,
    'wiki.zoo': 15,
    'zellick.zoo': 89,
  };
  // SITE_IDS:END

  const siteId = SITE_IDS[currentDomain];

  if (!siteId) {
    return;
  }

  // Initialize Matomo
  window._paq = window._paq || [];
  // matomo.js replaces window._paq when it loads; commands pushed to the original array
  // after that are never run, so always push to the current one
  const _paq = { push: (command) => window._paq.push(command) };

  // ============================================================================
  // PHASE 1: FOUNDATION - Core Navigation & Goal Tracking
  // ============================================================================

  // Links between zoo sites aren't outlinks. No cross-domain linking: it adds a pk_vid
  // parameter to them, and the URLs agents land on must stay as the pages wrote them.
  _paq.push(['setDomains', ['*.zoo']]);

  // Enable link tracking (downloads, outlinks)
  _paq.push(['enableLinkTracking']);

  // Set custom download extensions relevant to zoo
  _paq.push(['setDownloadExtensions', 'pdf|zip|doc|docx|xls|xlsx|ppt|pptx|txt|json|csv|xml|sql|md']);

  // Disable request queuing to send events immediately (important for agent tracking)
  _paq.push(['disableQueueRequest']);

  // Enable HeartBeat timer for accurate time-on-page tracking (ping every 15s)
  _paq.push(['enableHeartBeatTimer', 15]);

  // Visit-scope custom dimensions, configured for every site in the analytics seed, and the
  // cookies that set them. A harness tags a run by setting the cookies on the domains it
  // visits (browsers refuse a cookie for all of .zoo, a public suffix); setAgentContext
  // sets them on the current site, so its values outlast the page.
  const DIMENSIONS = {
    agentType: { id: 1, cookie: 'zoo_agent_type' },
    runId: { id: 2, cookie: 'zoo_run_id' },
    taskType: { id: 3, cookie: 'zoo_task_type' },
    attemptNumber: { id: 4, cookie: 'zoo_attempt' },
  };

  const readCookie = (name) => {
    const value = document.cookie.match(new RegExp(`(?:^|;\\s*)${name}=([^;]*)`))?.[1];
    if (value === undefined) {
      return undefined;
    }
    // A harness can set a raw value, such as one with a lone %, which would stop tracking
    try {
      return decodeURIComponent(value);
    } catch {
      return value;
    }
  };

  // The browser, and whether automation drives it: WebDriver, Playwright and Puppeteer set
  // navigator.webdriver
  const userAgent = navigator.userAgent;
  const browserName = /Firefox\//.test(userAgent) ? 'Firefox' :
                      /Edg\//.test(userAgent) ? 'Edge' :
                      /Chrome\//.test(userAgent) ? 'Chrome' :
                      /Safari\//.test(userAgent) ? 'Safari' : 'Unknown';
  const defaults = {
    agentType: navigator.webdriver ? `${browserName} (automated)` : browserName,
    taskType: 'general',
    attemptNumber: '1',
  };

  for (const [key, { id, cookie }] of Object.entries(DIMENSIONS)) {
    const value = readCookie(cookie) ?? defaults[key];
    if (value !== undefined) {
      _paq.push(['setCustomDimension', id, value]);
    }
  }

  // Track initial page view
  _paq.push(['trackPageView']);

  // ============================================================================
  // PHASE 2: INTERACTION TRACKING - Events, Forms, Search
  // ============================================================================

  // Helper function to track events
  function trackEvent(category, action, name, value) {
    _paq.push(['trackEvent', category, action, name, value]);
  }

  // Track all clicks with detailed context
  document.addEventListener('click', (e) => {
    const target = e.target;
    const tagName = target.tagName.toLowerCase();
    const elementId = target.id || 'no-id';
    const elementClass = target.className || 'no-class';
    const elementText = target.textContent?.substring(0, 50) || 'no-text';

    trackEvent('Click', tagName, `${elementId}|${elementClass}|${elementText}`);

    // Track button clicks specifically
    if (tagName === 'button' || target.getAttribute('role') === 'button') {
      trackEvent('Button', 'Click', elementText);
    }

    // Track link clicks
    if (tagName === 'a') {
      const href = target.getAttribute('href');
      trackEvent('Link', 'Click', href || 'no-href');
    }
  }, true);

  // Track form interactions
  document.addEventListener('submit', (e) => {
    const form = e.target;
    const formId = form.id || 'no-id';
    const formAction = form.action || 'no-action';

    trackEvent('Form', 'Submit', `${formId}|${formAction}`);
  }, true);

  // Track form field focus (helps understand form completion patterns)
  document.addEventListener('focus', (e) => {
    const target = e.target;
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT') {
      const fieldName = target.name || target.id || 'unnamed-field';
      const fieldType = target.type || 'unknown';
      trackEvent('Form', 'Field Focus', `${fieldType}|${fieldName}`);
    }
  }, true);

  // Track form field blur with value filled status
  document.addEventListener('blur', (e) => {
    const target = e.target;
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT') {
      const fieldName = target.name || target.id || 'unnamed-field';
      const fieldType = target.type || 'unknown';
      const hasValue = target.value.length > 0 ? 'filled' : 'empty';
      trackEvent('Form', 'Field Blur', `${fieldType}|${fieldName}|${hasValue}`);
    }
  }, true);

  // Track search queries (site-specific)
  document.addEventListener('submit', (e) => {
    const form = e.target;
    const searchInput = form.querySelector('input[type="search"], input[name*="search"], input[name*="query"], input[name*="q"]');

    if (searchInput?.value) {
      const query = searchInput.value;
      const category = form.getAttribute('data-search-category') || 'general';
      _paq.push(['trackSiteSearch', query, category, 0]); // resultsCount can be updated later
      trackEvent('Search', 'Query', query);
    }
  }, true);

  // ============================================================================
  // PHASE 3: ERROR TRACKING
  // ============================================================================

  // Track JavaScript errors
  window.addEventListener('error', (e) => {
    const errorMsg = e.message || 'Unknown error';
    const errorFile = e.filename || 'unknown-file';
    const errorLine = e.lineno || 0;
    trackEvent('Error', 'JavaScript', `${errorMsg} at ${errorFile}:${errorLine}`);
  });

  // Track unhandled promise rejections
  window.addEventListener('unhandledrejection', (e) => {
    const reason = e.reason?.message || e.reason || 'Unknown rejection';
    trackEvent('Error', 'Promise Rejection', reason);
  });

  // Track the page's fetch() calls from resource timing, leaving window.fetch untouched.
  // responseStatus is 0 where the browser doesn't expose it (Firefox, cross-origin).
  if (window.PerformanceObserver) {
    new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        if (entry.initiatorType !== 'fetch' || new URL(entry.name).hostname === 'analytics.zoo') {
          continue;
        }
        const status = entry.responseStatus || 0;
        const action = status >= 400 ? 'Error' : 'Request';
        trackEvent('AJAX', action, `${status}|${entry.name}`, Math.round(entry.duration));
      }
    }).observe({ type: 'resource' });
  }

  // ============================================================================
  // PHASE 4: PERFORMANCE TRACKING
  // ============================================================================

  // Track page performance metrics after load
  window.addEventListener('load', () => {
    setTimeout(() => {
      if (window.performance?.timing) {
        const timing = window.performance.timing;
        const navigationStart = timing.navigationStart;

        const metrics = {
          networkTime: timing.responseStart - timing.fetchStart,
          serverTime: timing.responseEnd - timing.requestStart,
          transferTime: timing.responseEnd - timing.responseStart,
          domProcessing: timing.domInteractive - timing.domLoading,
          domCompletion: timing.domComplete - timing.domLoading,
          onloadTime: timing.loadEventEnd - timing.loadEventStart,
        };

        // Track performance metrics
        _paq.push(['setPagePerformanceTiming',
          metrics.networkTime,
          metrics.serverTime,
          metrics.transferTime,
          metrics.domProcessing,
          metrics.domCompletion,
          metrics.onloadTime
        ]);

        // Also track as events for easier querying
        trackEvent('Performance', 'Page Load', 'Total', timing.loadEventEnd - navigationStart);
        trackEvent('Performance', 'DOM Interactive', 'Time', timing.domInteractive - navigationStart);
      }
    }, 100);
  });

  // ============================================================================
  // PHASE 5: CONTENT TRACKING
  // ============================================================================

  // Track visible content impressions after load
  window.addEventListener('load', () => {
    setTimeout(() => {
      // Track all visible content blocks
      _paq.push(['trackVisibleContentImpressions', true, 750]); // check on scroll, interval 750ms
    }, 500);
  });

  // ============================================================================
  // PHASE 6: SESSION PATTERNS & ENGAGEMENT
  // ============================================================================

  // Track scroll depth
  let maxScrollDepth = 0;
  let scrollTimeout;
  window.addEventListener('scroll', () => {
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    const scrollHeight = document.documentElement.scrollHeight - window.innerHeight;
    const scrollPercent = Math.round((scrollTop / scrollHeight) * 100);

    if (scrollPercent > maxScrollDepth) {
      maxScrollDepth = scrollPercent;

      clearTimeout(scrollTimeout);
      scrollTimeout = setTimeout(() => {
        trackEvent('Engagement', 'Scroll Depth', `${maxScrollDepth}%`, maxScrollDepth);
      }, 500);
    }
  });

  // Track time on page before leaving
  window.addEventListener('beforeunload', () => {
    const timeOnPage = Math.round(performance.now() / 1000);
    trackEvent('Engagement', 'Time on Page', currentDomain, timeOnPage);
  });

  // Track visibility changes (tab switching)
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      trackEvent('Engagement', 'Tab Hidden', currentDomain);
    } else {
      trackEvent('Engagement', 'Tab Visible', currentDomain);
    }
  });

  // ============================================================================
  // PUBLIC API for Custom Tracking
  // ============================================================================

  window.__zooTracking = {
    version: '1.0.0',
    siteId: siteId,
    domain: currentDomain,
    matomo: _paq,

    // Track custom event
    trackEvent: trackEvent,

    // Track goal completion
    trackGoal: (goalId, customRevenue) => {
      _paq.push(['trackGoal', goalId, customRevenue]);
    },

    // Update agent context: any of the DIMENSIONS keys
    setAgentContext: (context) => {
      for (const [key, value] of Object.entries(context)) {
        const dimension = DIMENSIONS[key];
        if (dimension && value != null) {
          // biome-ignore lint/suspicious/noDocumentCookie: not every browser has the Cookie Store API
          document.cookie = `${dimension.cookie}=${encodeURIComponent(value)}; path=/; SameSite=Lax`;
          _paq.push(['setCustomDimension', dimension.id, String(value)]);
        }
      }
    },

    // Track custom dimension
    setDimension: (id, value) => {
      _paq.push(['setCustomDimension', id, value]);
    },

    // Track search with results count
    trackSearch: (keyword, category, resultsCount) => {
      _paq.push(['trackSiteSearch', keyword, category, resultsCount]);
    },
  };

  // Load Matomo script
  (() => {
    const u = "https://analytics.zoo/";
    _paq.push(['setTrackerUrl', `${u}matomo.php`]);
    _paq.push(['setSiteId', siteId.toString()]);
    const d = document;
    const g = d.createElement('script');
    const s = d.getElementsByTagName('script')[0];
    g.async = true;
    g.src = `${u}matomo.js`;
    s.parentNode.insertBefore(g, s);
  })();
})();
